(function(){'use strict';var isMobile=/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)||window.innerWidth<768;var loadedSlots={};function isSlotBlockedByDevice(element){if(!element)return true;if(isMobile&&(element.classList.contains('ad-slot--desktop-only')||element.classList.contains('ad-sidebar')))return true;if(!isMobile&&element.classList.contains('ad-slot--mobile-only'))return true;if(element.offsetWidth===0&&element.offsetHeight===0)return true;return false;}
function loadAdSenseAd(container){if(!container||isSlotBlockedByDevice(container))return;var cRect=container.getBoundingClientRect();if(cRect.width<=0||container.offsetWidth<=0||container.offsetParent===null)return;var insTags=container.querySelectorAll('ins.adsbygoogle:not([data-ad-status="unfilled"]):not([data-adsbygoogle-status="done"])');for(var i=0;i<insTags.length;i++){var ins=insTags[i];var slotId=ins.id||(ins.getAttribute('data-ad-slot')+'_'+i);if(loadedSlots['adsense_'+slotId])continue;if(isSlotBlockedByDevice(container))continue;if(container.offsetWidth<=0||cRect.width<=0)continue;loadedSlots['adsense_'+slotId]=true;try{(window.adsbygoogle=window.adsbygoogle||[]).push({});}catch(e){console.error("AdSense Error: ",e);}}}
window.initAdsInContainer=function(containerElement){if(!containerElement)return;loadAdSenseAd(containerElement);};function initGlobalAds(){var allAdsenseIns=document.querySelectorAll('ins.adsbygoogle');for(var j=0;j<allAdsenseIns.length;j++){var ins=allAdsenseIns[j];var parentTab=ins.closest('.tab-content');if(!parentTab||parentTab.classList.contains('active')){var container=ins.parentElement;loadAdSenseAd(container);}}}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initGlobalAds);}else{initGlobalAds();}})();